fn is_greater(n: i32, a: Vec<i32>) -> bool {
    // Iterate through each element in the array.
    // If any element is greater than or equal to n, we know
    // n is not strictly greater than every element, so return false.
    for &x in &a {
        if x >= n {
            return false;
        }
    }
    // If we never found an element >= n, then n is strictly greater
    // than all elements (or the array was empty), so return true.
    true
}

